using System.Text.Json;
using Microsoft.Data.Sqlite;
using QuickPrompt.Local;
using QuickPrompt.Web.Infrastructure;
using Xunit;
namespace QuickPrompt.Web.Tests;
public sealed class StoreTests : IDisposable
{
    private readonly string directory=Path.Combine(Path.GetTempPath(),"quickprompt-tests-"+Guid.NewGuid());
    private LocalStore Store(string name="test")=>new(Path.Combine(directory,name+".sqlite"));
    private static Template New()=>new(){Title="Ficción",Template="Hola <nombre>",Description="Prueba"};
    [Fact] public void RealSqlitePersistsMigrationAndVersionAfterRestart(){var s=Store();var t=s.Save(New());var after=Store();Assert.Single(after.Templates());Assert.Single(after.Versions(t.Id));Assert.Equal("ok",after.CheckIntegrity());}
    [Fact] public void DuplicateIdentityUpdatesWithOptimisticConcurrency(){var s=Store();var t=s.Save(New());var stale=JsonSerializer.Deserialize<Template>(JsonSerializer.Serialize(t,LocalStore.Json),LocalStore.Json)!;t.Template="Nuevo <nombre>";s.Save(t);Assert.Throws<ConflictException>(()=>s.Save(stale));Assert.Equal(2,s.Versions(t.Id).Count);}
    [Fact] public void CompileIsAtomicOnMissingVariable(){var s=Store();var t=s.Save(New());Assert.Throws<ValidationException>(()=>s.Compile(t.Id,new()));Assert.Empty(s.History());Assert.Equal(0,s.Templates().Single().Uses);}
    [Fact] public void HistoryOptInAndForget(){var s=Store();var t=s.Save(New());var h=s.Compile(t.Id,new(){{"nombre","Ana ficticia"}});Assert.Empty(h.Values);s.SaveSettings(new(RememberValues:true));Assert.Single(s.Compile(t.Id,new(){{"nombre","B ficticia"}}).Values);s.SaveExecution(new(Guid.NewGuid(),h.Id,"qwen3:8b","ok",1,DateTime.UtcNow));s.ClearHistory();Assert.Empty(s.History());Assert.Empty(s.Executions());}
    [Fact] public void FavoritesArchiveRestoreAndFinalFavorites(){var s=Store();var t=s.Save(New());t.ToggleFavorite();s.Save(t);Assert.True(s.Templates().Single().IsFavorite);var h=s.Compile(t.Id,new(){{"nombre","X"}});s.FavoriteFinal(h);Assert.True(s.History().Single().Favorite);t.MarkAsDeleted();s.Save(t);Assert.Throws<ValidationException>(()=>s.Compile(t.Id,new(){{"nombre","X"}}));t.IsActive=true;t.DeletedAt=null;s.Save(t);Assert.NotNull(s.Compile(t.Id,new(){{"nombre","X"}}));}
    [Fact] public void ImportRoundTripNoOverwriteAndIdempotent(){var s=Store();var t=s.Save(New());s.Compile(t.Id,new(){{"nombre","Ejemplo"}});var json=s.Export();var target=Store("target");Assert.Equal(1,target.Import(json));Assert.Equal(0,target.Import(json));var incoming=JsonSerializer.Deserialize<Archive>(json,LocalStore.Json)!;incoming.Templates[0].Title="Do not overwrite";Assert.Equal(0,target.Import(JsonSerializer.Serialize(incoming,LocalStore.Json)));Assert.Equal("Ficción",target.Templates().Single().Title);}
    [Fact] public void FullBackupRestorePreservesAllEntities(){var s=Store();var t=s.Save(New());var h=s.Compile(t.Id,new(){{"nombre","X"}});s.SaveExecution(new(Guid.NewGuid(),h.Id,"qwen3:8b","respuesta",123,DateTime.UtcNow));var p=new AiProposal(Guid.NewGuid(),t.Id,t.Revision,"Mejor <nombre>",["claridad"],[],[],["nombre"],"qwen3:8b");s.SaveProposal(p);var snapshot=s.Export();s.ClearHistory();s.Import(snapshot,true);Assert.Equal(snapshot,s.Export());Assert.Equal("ok",s.CheckIntegrity());}
    [Theory][InlineData("not json")][InlineData("{\"schemaVersion\":999}")][InlineData("{\"Title\":\"No template\"}")][InlineData("{\"schemaVersion\":1,\"templates\":null}")]
    public void InvalidImportCannotDestroyExistingData(string json){var s=Store();s.Save(New());var before=s.Export();Assert.ThrowsAny<Exception>(()=>s.Import(json,true));Assert.Equal(before,s.Export());}
    [Fact] public void InvalidLaterItemRollsBackEntireImport(){var s=Store();var input=new[]{New(),new Template{Title="Bad"}};Assert.Throws<ValidationException>(()=>s.Import(JsonSerializer.Serialize(input,LocalStore.Json)));Assert.Empty(s.Templates());}
    [Fact] public void ProposalDoesNotMutateAndAcceptVersionsAtomically(){var s=Store();var t=s.Save(New());var p=new AiProposal(Guid.NewGuid(),t.Id,t.Revision,"Mejor <nombre>",["claridad"],[],[],["nombre"],"qwen3:8b");s.SaveProposal(p);Assert.Equal("Hola <nombre>",s.Templates().Single().Template);t.Template=p.Text;s.Save(t,"AI accepted",p.Id);Assert.Equal(2,s.Versions(t.Id).Count);Assert.Contains("accepted",s.Export());Assert.Throws<ConflictException>(()=>s.Save(t,"AI accepted",p.Id));Assert.Equal(2,s.Versions(t.Id).Count);}
    [Fact] public void RejectKeepsOriginal(){var s=Store();var t=s.Save(New());var p=new AiProposal(Guid.NewGuid(),t.Id,t.Revision,"changed",[],[],[],[],"qwen3:8b");s.SaveProposal(p);s.Reject(p);Assert.Single(s.Versions(t.Id));Assert.Equal("Hola <nombre>",s.Templates().Single().Template);}
    [Fact] public void JsonLegacySingleObjectCompatible()=>Assert.Equal(1,Store().Import("{\"Title\":\"Legado\",\"Template\":\"Hola <x>\",\"Description\":\"test\",\"VariablesJson\":\"{}\"}"));
    [Fact] public void JsonLegacyDefaultsPreserved(){var s=Store();s.Import("{\"Title\":\"Legado\",\"Template\":\"Hola <x>\",\"Description\":\"test\",\"VariablesJson\":\"{\\\"x\\\":\\\"base\\\"}\"}");Assert.Equal("Hola base",s.Compile(s.Templates().Single().Id,new()).Text);}
    [Fact] public async Task SelectedLegacyDbImportedWithoutChangingSource()
    {
        var s=Store();var path=Path.Combine(directory,"legacy.sqlite");using(var db=new SqliteConnection($"Data Source={path};Pooling=False")){db.Open();using var c=db.CreateCommand();c.CommandText="CREATE TABLE PromptTemplate(Id TEXT,Title TEXT,Template TEXT,Description TEXT,Category INTEGER,VariablesJson TEXT,IsFavorite INTEGER); INSERT INTO PromptTemplate VALUES($id,'Legado','Hola <nombre>','Prueba',0,'{}',1)";c.Parameters.AddWithValue("$id",Guid.NewGuid().ToString());c.ExecuteNonQuery();}
        var before=File.ReadAllBytes(path);await using(var source=File.OpenRead(path)){var json=await LegacyImporter.Convert(source);Assert.Equal(1,s.Import(json));}Assert.Equal(before,File.ReadAllBytes(path));Assert.True(s.Templates().Single().IsFavorite);
    }
    [Fact] public async Task LegacyDatesFinalsAndHistorySurviveMigration()
    {
        var s=Store();var path=Path.Combine(directory,"full-legacy.sqlite");var id=Guid.NewGuid();var finalId=Guid.NewGuid();var historyId=Guid.NewGuid();var date=new DateTime(2024,1,2,3,4,5,DateTimeKind.Utc);
        using(var db=new SqliteConnection($"Data Source={path};Pooling=False")){db.Open();using var c=db.CreateCommand();c.CommandText="CREATE TABLE PromptTemplate(Id TEXT,Title TEXT,Template TEXT,Description TEXT,Category INTEGER,VariablesJson TEXT,IsFavorite INTEGER,CreatedAt INTEGER,UpdatedAt INTEGER); INSERT INTO PromptTemplate VALUES($id,'Migrada','Hola <nombre>','test',0,'{}',1,$ticks,$ticks); CREATE TABLE FinalPrompt(Id TEXT,SourcePromptId TEXT,CompletedText TEXT,IsFavorite INTEGER,CreatedAt INTEGER);INSERT INTO FinalPrompt VALUES($final,$id,'Hola ejemplo',1,$ticks); CREATE TABLE ExecutionHistoryEntry(Id TEXT,PromptCompiled TEXT,ExecutedAt INTEGER,IsDeleted INTEGER);INSERT INTO ExecutionHistoryEntry VALUES($history,'Consulta anterior',$ticks,0);";c.Parameters.AddWithValue("$id",id.ToString());c.Parameters.AddWithValue("$final",finalId.ToString());c.Parameters.AddWithValue("$history",historyId.ToString());c.Parameters.AddWithValue("$ticks",date.Ticks);c.ExecuteNonQuery();}
        var bytes=File.ReadAllBytes(path);await using(var source=File.OpenRead(path)){var json=await LegacyImporter.Convert(source);s.Import(json);Assert.Equal(0,s.Import(json));}
        Assert.Equal(bytes,File.ReadAllBytes(path));Assert.Equal(date,s.Templates().Single().CreatedAt);Assert.Equal(2,s.History().Count);var final=s.History().Single(h=>h.Id==finalId);Assert.Equal(id,final.TemplateId);Assert.True(final.Favorite);Assert.Equal(date,final.CreatedAt);Assert.Empty(s.Executions());
    }
    [Fact] public void VersionedImportPreservesHistoryAndVersions(){var s=Store();var t=s.Save(New());t.Template="Otra <nombre>";s.Save(t);var h=s.Compile(t.Id,new(){{"nombre","X"}});s.SaveExecution(new(Guid.NewGuid(),h.Id,"qwen3:8b","Respuesta",42,DateTime.UtcNow));var target=Store("copy");target.Import(s.Export());Assert.Equal(2,target.Versions(t.Id).Count);Assert.Single(target.History());Assert.Single(target.Executions());Assert.Equal(0,target.Import(s.Export()));Assert.Single(target.Executions());}
    [Theory][InlineData("{\"schemaVersion\":1,\"templates\":[],\"versions\":[null],\"history\":[],\"executions\":[],\"proposals\":[],\"preferences\":{}}")][InlineData("{\"Title\":\"one\",\"title\":\"two\",\"Template\":\"text\"}")]
    public void NullRecordsAndDuplicateJsonKeysFailWithoutDataLoss(string json){var s=Store();s.Save(New());var before=s.Export();Assert.Throws<ValidationException>(()=>s.Import(json,true));Assert.Equal(before,s.Export());}
    [Fact] public void DuplicateGuidsRejectedInsteadOfOverwritingWithinFile(){var t=New();Assert.Throws<ValidationException>(()=>Store().Import(JsonSerializer.Serialize(new[]{t,t},LocalStore.Json)));}
    [Fact] public void RejectedAiCannotBeAcceptedOrChangeVariables(){var s=Store();var t=s.Save(New());var p=new AiProposal(Guid.NewGuid(),t.Id,t.Revision,"Bad <other>",[],[],[],["other"],"qwen3:8b");s.SaveProposal(p);t.Template=p.Text;Assert.Throws<ConflictException>(()=>s.Save(t,"AI accepted",p.Id));Assert.Single(s.Versions(t.Id));}
    public void Dispose(){if(Directory.Exists(directory))Directory.Delete(directory,true);}
}
